1	import { api, type SearchResult, type ReviewEntry } from './api';
2	import { embedTexts, embedSingle, ensureModelReady, getModelMeta } from './embedding';
3	import { setStatus, showToast, loadState, saveState, type AppState } from './state';
4	
5	const state: AppState = {
6	  currentCourse: null,
7	  collections: [],
8	  reviewProgress: new Map(),
9	  lastSearchTime: null,
10	  modelReady: false,
11	  importProgress: null,
12	};
13	
14	function el(tag: string, attrs?: Record<string, string>, ...children: (string | Node)[]): HTMLElement {
15	  const node = document.createElement(tag);
16	  if (attrs) {
17	    for (const [k, v] of Object.entries(attrs)) {
18	      if (k === 'className') node.className = v;
19	      else if (k === 'textContent') node.textContent = v;
20	      else if (k.startsWith('data-')) node.setAttribute(k, v);
21	      else node.setAttribute(k, v);
22	    }
23	  }
24	  for (const child of children) {
25	    if (typeof child === 'string') node.appendChild(document.createTextNode(child));
26	    else node.appendChild(child);
27	  }
28	  return node;
29	}
30	
31	function clearChildren(node: HTMLElement) {
32	  while (node.firstChild) node.removeChild(node.firstChild);
33	}
34	
35	export function initUI() {
36	  const saved = loadState();
37	  if (saved.currentCourse) state.currentCourse = saved.currentCourse;
38	  setupNav();
39	  renderCourses();
40	  renderImport();
41	  renderSearch();
42	  renderReview();
43	  initModel();
44	}
45	
46	function setupNav() {
47	  document.querySelectorAll('.nav-btn').forEach((btn) => {
48	    btn.addEventListener('click', () => {
49	      document.querySelectorAll('.nav-btn').forEach((b) => b.classList.remove('active'));
50	      document.querySelectorAll('.tab-content').forEach((t) => t.classList.remove('active'));
51	      btn.classList.add('active');
52	      const tab = btn.getAttribute('data-tab');
53	      if (tab) {
54	        document.getElementById(`tab-${tab}`)?.classList.add('active');
55	        if (tab === 'review') refreshWeakPoints();
56	        if (tab === 'courses') refreshCollections();
57	      }
58	    });
59	  });
60	}
61	
62	async function initModel() {
63	  setStatus('正在加载向量化模型...');
64	  try {
65	    const meta = await ensureModelReady();
66	    state.modelReady = true;
67	    const sizeMB = (meta.modelSizeBytes / (1024 * 1024)).toFixed(1);
68	    const info = `模型就绪 [${meta.backend.toUpperCase()}] dtype=${meta.dtype} ${sizeMB}MB ${meta.loadTimeMs}ms`;
69	    setStatus(info);
70	    showToast('向量化模型加载完成', 'success');
71	  } catch (e) {
72	    const msg = e instanceof Error ? e.message : String(e);
73	    setStatus('模型加载失败: ' + msg);
74	    showToast('模型加载失败，请检查 /models 目录', 'error');
75	  }
76	}
77	
78	// ─── Courses Tab ───
79	
80	function renderCourses() {
81	  const container = document.getElementById('tab-courses');
82	  if (!container) return;
83	  clearChildren(container);
84	
85	  const newCard = el('div', { className: 'card' });
86	  newCard.appendChild(el('h3', {}, '新建课程'));
87	  const row = el('div', { className: 'row' });
88	  const input = el('input', { type: 'text', id: 'new-course-id', placeholder: '课程 ID（英文，如 math101)' }) as HTMLInputElement;
89	  const btn = el('button', { className: 'primary', id: 'btn-create-course' }, '创建');
90	  row.appendChild(input);
91	  row.appendChild(btn);
92	  newCard.appendChild(row);
93	  container.appendChild(newCard);
94	
95	  const listCard = el('div', { className: 'card' });
96	  listCard.appendChild(el('h3', {}, '课程列表'));
97	  const listEl = el('div', { id: 'course-list' });
98	  listEl.appendChild(el('div', { className: 'empty-hint' }, '加载中...'));
99	  listCard.appendChild(listEl);
100	  container.appendChild(listCard);
101	
102	  btn.addEventListener('click', createCourse);
103	  refreshCollections();
104	}
105	
106	async function refreshCollections() {
107	  try {
108	    state.collections = await api.listCollections();
109	    renderCourseList();
110	  } catch (e) {
111	    const msg = e instanceof Error ? e.message : String(e);
112	    const listEl = document.getElementById('course-list');
113	    if (listEl) {
114	      clearChildren(listEl);
115	      listEl.appendChild(el('div', { className: 'empty-hint' }, `加载失败: ${msg}`));
116	    }
117	  }
118	}
119	
120	function renderCourseList() {
121	  const listEl = document.getElementById('course-list');
122	  if (!listEl) return;
123	  clearChildren(listEl);
124	
125	  if (state.collections.length === 0) {
126	    listEl.appendChild(el('div', { className: 'empty-hint' }, '暂无课程，请先创建'));
127	    return;
128	  }
129	
130	  for (const col of state.collections) {
131	    const card = el('div', { className: 'card' });
132	    const row = el('div', { className: 'row' });
133	    row.style.marginBottom = '0';
134	
135	    const info = el('div');
136	    info.style.flex = '2';
137	    const h3 = el('h3');
138	    h3.textContent = col.courseId + ' ';
139	    if (state.currentCourse === col.courseId) {
140	      const badge = el('span', { className: 'badge badge-mastery-2' }, '当前');
141	      h3.appendChild(badge);
142	    }
