300	function splitIntoChunks(text: string, size: number, overlap: number): string[] {
301	  const sentences = text.match(/[^。！？.!?\n]+[。！？.!?\n]?/g) || [text];
302	  const chunks: string[] = [];
303	  let current = '';
304	  for (const sentence of sentences) {
305	    if (current.length + sentence.length > size && current.length > 0) {
306	      chunks.push(current.trim());
307	      const words = current.split(/\s+/);
308	      let keep = '';
309	      let keepLen = 0;
310	      for (let i = words.length - 1; i >= 0; i--) {
311	        if (keepLen + words[i].length > overlap) break;
312	        keep = words[i] + ' ' + keep;
313	        keepLen += words[i].length + 1;
314	      }
315	      current = keep.trim() + sentence;
316	    } else {
317	      current += sentence;
318	    }
319	  }
320	  if (current.trim()) chunks.push(current.trim());
321	  return chunks;
322	}
