324	interface ParsedFile {
325	  fileName: string;
326	  chunks: Array<{ id: string; text: string; fileName: string; chunkIndex: number }>;
327	}
328	
329	function parseFile(fileName: string, content: string, chunkSize: number, chunkOverlap: number): ParsedFile {
330	  const chunks: ParsedFile['chunks'] = [];
331	  if (fileName.endsWith('.json')) {
332	    try {
333	      const arr = JSON.parse(content);
334	      if (Array.isArray(arr)) {
335	        arr.forEach((item: { id?: string; title?: string; text?: string }, idx: number) => {
336	          const text = item.text || item.title || '';
337	          if (!text) return;
338	          const subChunks = splitIntoChunks(text, chunkSize, chunkOverlap);
339	          subChunks.forEach((c, ci) => {
340	            chunks.push({
341	              id: `${item.id || idx}_${ci}`,
342	              text: c,
343	              fileName: item.title || fileName,
344	              chunkIndex: ci,
345	            });
346	          });
347	        });
348	      }
349	    } catch {
350	      const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
351	      textChunks.forEach((c, i) => {
352	        chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
353	      });
354	    }
355	  } else {
356	    const textChunks = splitIntoChunks(content, chunkSize, chunkOverlap);
357	    textChunks.forEach((c, i) => {
358	      chunks.push({ id: `${fileName}_${i}`, text: c, fileName, chunkIndex: i });
359	    });
360	  }
361	  return { fileName, chunks };
362	}
