639	function highlightInto(parent: HTMLElement, text: string, query: string) {
640	  if (!query.trim()) {
641	    parent.appendChild(document.createTextNode(text));
642	    return;
643	  }
644	  const words = query.split(/\s+/).filter(Boolean);
645	  if (words.length === 0) {
646	    parent.appendChild(document.createTextNode(text));
647	    return;
648	  }
649	  const escaped = words.map((w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
650	  const regex = new RegExp(`(${escaped.join('|')})`, 'gi');
651	  const parts = text.split(regex);
652	  for (const part of parts) {
653	    if (regex.test(part)) {
654	      const mark = el('mark');
655	      mark.textContent = part;
656	      parent.appendChild(mark);
657	    } else {
658	      parent.appendChild(document.createTextNode(part));
659	    }
660	    regex.lastIndex = 0;
661	  }
662	}
